    c.tick++;
    for (var w = 0; w < ways.length; w++) {
      if (ways[w].tag === tag) { ways[w].age = c.tick; return { hit: true, set: set, way: w, tag: tag }; }
    }
    var lru = 0;
    for (var k = 1; k < ways.length; k++) if (ways[k].age < ways[lru].age) lru = k;
    var evicted = ways[lru].tag;
    ways[lru].tag = tag;
