  var note0 = btbEl("div", "bb-hint", "immutable, baked at tapeout");
  td0n.appendChild(note0);
  tr0.appendChild(td0n);
  tr0.appendChild(btbEl("td", "bb-mono", "64 KB"));
  tr0.appendChild(btbEl("td", "bb-mono", "baked"));
