    var h = rrEl("h4", null, s.judged ? "CERTIFIED: " + s.verdict : "VOID: THE CORRECT CALL WAS " + p.verdict);
    box.appendChild(h);
    var why = rrEl("p", "rr-why", p.why);
    box.appendChild(why);
