    cert3.addEventListener("click", function () {
      t3.committed = true;
      clLog(clCertText(2), "ok");
      clMaybeBenchDone();
      clPop(c3);
    });

    /* ---------- completion banner ---------- */
    var banner = clEl("div", "cl-banner");
    banner.id = "clBanner";
    banner.appendChild(clEl("h3", null, "THE CELL ROOM, CERTIFIED"));
